import * as THREE from 'three';

import { Addon } from './';
import { loadFBX, loadFBXWithMat } from '../../../../../utils/ThreeUtils';

export class DroneDevice {
	public addon: Addon;

	private mesh: THREE.Group;

	constructor(addon: Addon) {
		this.addon = addon;
		this.mesh = new THREE.Group();
		this.mesh.name = 'DroneDevice';
		this.loadSolarPanel([addon.hypercubeParametric.configurator.BASE_URL + 'DroneDevice.fbx'], 0.25);
		// this.loadSolarPanel([process.env.PUBLIC_URL + '/static/data/LaserDevice-.fbx'], 0.01);
	}
	private loadSolarPanel = async (files, scale) => {
		// console.log(files, scale);
		try {
			const loadPromises = files.map((file) =>
				// loadFBX(
				// 	file,
				// 	scale,
				// 	this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.rendererCore.useWebGPU,
				// 	this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.isPerformanceMode,
				// 	this.addon.hypercubeParametric.configurator.materials.clippingPlanes
				// )

				loadFBXWithMat(
					file,
					scale,
					this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.rendererCore.useWebGPU,
					this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.isPerformanceMode,
					this.addon.hypercubeParametric.configurator.materials.clippingPlanes,
					this.addon.hypercubeParametric.configurator.materials.MaterialClass,
					this.addon.hypercubeParametric.configurator.materials.addonMaterial
				)
			);

			const fbxModels = await Promise.all(loadPromises);
			// fbxModels[0].position.y = -10.8;
			// console.log('======');
			// console.log(fbxModels);
			// fbxModels[0].children[2].material[1].color.r = 0;
			// fbxModels[0].children[2].material[1].color.g = 50 / 255;
			// fbxModels[0].children[2].material[1].color.b = 1.0;

			this.mesh = fbxModels[0];
			this.mesh.children[2].material[1].color.r = 0;
			this.mesh.children[2].material[1].color.g = 50 / 255;
			this.mesh.children[2].material[1].color.b = 1.0;

			this.syncSizes();

			this.addon.hypercubeParametric.configurator.sceneWrapper.scene.add(this.mesh);
		} catch (error) {
			console.error('fail to load :', error);
		}
	};
	public syncSizes() {
		if (this.mesh) {
			this.mesh.position.x = this.addon.hypercubeParametric.params.width * 0.5 - this.addon.hypercubeParametric.params.thickness * 0.5;
			this.mesh.position.y = this.addon.hypercubeParametric.params.height + this.addon.hypercubeParametric.params.groundY - 0.5;
			this.mesh.position.z = this.addon.hypercubeParametric.params.length * 0.5 - this.addon.hypercubeParametric.params.thickness * 0.5;
		}
	}
	public toggleVisibility() {
		this.mesh.visible = !this.mesh.visible;
	}
}
