import * as THREE from 'three';
import { VRButton } from 'three/examples/jsm/webxr/VRButton.js';

import { WebGLRenderer } from 'three';
import { WebGPURenderer } from 'three/webgpu';

import { createRenderer } from '../../utils/ThreeUtils';

import Stats from 'stats.js';
import { RendererCore } from '..';

export class RendererWrapper {
	public core: RendererCore;
	public scene: THREE.Scene;
	public renderer: WebGLRenderer | WebGPURenderer | undefined = undefined;

	public canvas: HTMLCanvasElement | undefined = undefined;

	public requestFrame: number | undefined = undefined;
	public deltaTime: number = 0;
	public t: number = 0;

	public divRenderingStatus: HTMLDivElement | undefined = undefined;
	private loadingDiv: HTMLDivElement | undefined = undefined;

	private _stats: Stats | undefined = undefined;
	private _clock: THREE.Clock | undefined = undefined;
	private _initPost: boolean = true;
	private _antialias: boolean = true;

	private _adaptiveRendering: boolean = false;
	private _keepRendering: boolean = true;
	private _forceRenderActive: boolean = false;
	private _isRendering: boolean = false;

	private idleTime: number = 0;
	private readonly MAX_IDLE_SECONDS: number = 1.0;
	private readonly TARGET_FPS: number;
	private readonly FRAME_INTERVAL: number;
	private readonly pixelRatio: number;

	public debuggerModeLog: boolean = false;
	private _t0: DOMHighResTimeStamp = 0;
	private _t1: DOMHighResTimeStamp = 0;
	private _frameNum: number = 0;
	private _timeSum: number = 0;
	private _lastFrameTime: DOMHighResTimeStamp = 0;

	constructor(threeCore: RendererCore, enableAdaptiveRendering: boolean = true, frameRate: number = 30, pixelRatio: number = Math.min(window.devicePixelRatio, 2)) {
		this.core = threeCore;
		THREE.Object3D.DEFAULT_UP.copy(this.core.upVector);

		this.TARGET_FPS = frameRate;
		this.FRAME_INTERVAL = 1000 / this.TARGET_FPS;
		this.pixelRatio = this.core.isPerformanceMode ? 1 : pixelRatio;
		this.keepRendering = true;
		this.adaptiveRendering = enableAdaptiveRendering;
	}

	public async init(): Promise<void> {
		try {
			this.appendLoading();
			this.canvas = document.createElement('canvas');

			this.scene = new THREE.Scene();
			this.scene.background = new THREE.Color(0xffffff);
			this.scene.castShadow = true;

			this.renderer = await createRenderer({
				canvas: this.canvas,
				alpha: !this.core.isPerformanceMode,
				antialias: this._antialias,
				// antialias: this.core.isPerformanceMode ? false : this._antialias,
				performanceMode: this.core.isPerformanceMode,
				useWebGPU: this.core.useWebGPU,
			});

			if (!this.renderer) throw new Error('Failed to create renderer');

			await this.initXR();

			this.renderer.setPixelRatio(this.pixelRatio);
			this.renderer.setSize(this.core.host.clientWidth, this.core.host.clientHeight);
			window.addEventListener('resize', this.resizeHandler);

			this.renderer.shadowMap.enabled = true;
			this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
			this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
			this.renderer.toneMappingExposure = 1.0;
			this.renderer.outputColorSpace = THREE.SRGBColorSpace;
			this.renderer.localClippingEnabled = true;

			this.renderer.domElement.id = 'hypercube-renderer';
			this.core.host.appendChild(this.renderer.domElement);
			this.core.host.appendChild(VRButton.createButton(this.renderer));

			this.initBinding();
		} catch (error) {
			console.error('Initialization failed:', error);
			throw error;
		}
	}
	async initXR() {
		this.renderer.xr.enabled = true;
		// const session = await navigator.xr.requestSession('inline');
		// this.renderer.xr.setSession(session);
		// console.log(session);
	}
	private initBinding(): void {
		this.core.scene = this.scene;
		this.core.renderer = this.renderer;
	}

	public toggleAdaptiveRendering(): void {
		this.adaptiveRendering = !this.adaptiveRendering;
	}

	public get adaptiveRendering(): boolean {
		return this._adaptiveRendering;
	}

	public set adaptiveRendering(value: boolean) {
		if (this._adaptiveRendering === value) return;
		this._adaptiveRendering = value;
		this.keepRendering = !value;
		this.idleTime = 0;
		this.loop();
	}

	public get keepRendering(): boolean {
		return this._keepRendering;
	}

	public set keepRendering(value: boolean) {
		if (this._keepRendering === value) return;
		this._keepRendering = value;
		if (this._clock) this._clock.start();
		this.loop();
	}

	/**
	 * Forces a single render frame, respecting FPS limits.
	 */
	public renderForce(): void {
		if (this._isRendering) {
			this.idleTime = 0;
			return;
		}

		this._forceRenderActive = true;
		this._keepRendering = true;
		this.idleTime = 0;
		this._frameNum = 0;
		this._timeSum = 0;
		this.loop();
	}
	public start(): void {
		this.removeLoadingGIFDom();

		if (this.core.debuggerMode) {
			this._stats = new Stats();
			this._stats.showPanel(0);
			Object.assign(this._stats.dom.style, {
				position: 'absolute',
				top: '0px',
				right: '0px',
				left: '',
			});
			this.core.host.appendChild(this._stats.dom);

			this.divRenderingStatus = document.createElement('div');
			Object.assign(this.divRenderingStatus.style, {
				fontSize: '11px',
				color: '#181835',
				fontWeight: '300',
			});
			this._stats.dom.appendChild(this.divRenderingStatus);
		}
		this._clock = new THREE.Clock();
		this._initPost = false;
	}
	public loop = (): void => {
		if (!this.renderer || !this.canvas || !this.core) {
			console.warn('Renderer or core not initialized, skipping loop');
			return;
		}

		const currentTime = performance.now();
		const timeSinceLastFrame = currentTime - this._lastFrameTime;

		if (timeSinceLastFrame < this.FRAME_INTERVAL) {
			this.requestFrame = requestAnimationFrame(this.loop);
			return;
		}

		this._lastFrameTime = currentTime - (timeSinceLastFrame % this.FRAME_INTERVAL);
		this.renderFrame();
	};
	private renderFrame(): void {
		if (!this.renderer || !this.core) return;

		const isWebGPU = this.core.useWebGPU;
		const isPerformanceMode = this.core.isPerformanceMode;

		if (this._adaptiveRendering && !this._keepRendering && this.idleTime >= this.MAX_IDLE_SECONDS) {
			this.updateRenderingStatus(false);
			this._isRendering = false;
			return;
		}

		this._t0 = performance.now();

		this.requestFrame = requestAnimationFrame(this.loop);
		this.updateRenderingStatus(true);

		this.deltaTime = this._clock?.getDelta() ?? 0;
		this.t += this.deltaTime;

		if (!this.core.readyBinding() || !this.core.ready) return;

		if (this._initPost) this.start();

		this._stats?.begin();
		this._isRendering = true;

		this.core.cameraWrapper.update();
		const sceneUpdated = this.core.update();

		if (sceneUpdated || !this._adaptiveRendering || this._keepRendering || this._forceRenderActive) {
			this.idleTime = 0;
		} else {
			this.idleTime += this.deltaTime;
		}

		if (isWebGPU || isPerformanceMode) {
			this.renderer.render(this.scene, this.core.cameraWrapper.camera);
		} else {
			this.core.postProcessingWrapper.render();
		}
		this._stats?.end();

		if (this._forceRenderActive) {
			this._forceRenderActive = false;
			if (this._adaptiveRendering) {
				this._keepRendering = false;
			}
		}

		this._t1 = performance.now();
		const renderDifference = this._t1 - this._t0;
		this._timeSum += renderDifference;
		this._frameNum += 1;

		if (this.debuggerModeLog) {
			this.logFrameMetrics(renderDifference);
		}
	}
	private updateRenderingStatus(isRendering: boolean): void {
		if (!this.divRenderingStatus) return;

		const avgFrameTime = this._frameNum > 0 ? (this._timeSum / this._frameNum).toFixed(2) : '0.00';
		const fps = this._frameNum > 0 ? (1000 / (this._timeSum / this._frameNum)).toFixed(1) : '0';

		this.divRenderingStatus.innerHTML = isRendering
			? `Web ${this.core.useWebGPU ? 'GPU' : 'GL'}: <br> Rendering... <br> FPS: ${fps} <br> Avg: ${avgFrameTime} ms/frame <br> Delta: ${this.deltaTime.toFixed(3)}s <br> PixelRatio: ${
					this.pixelRatio
			  }`
			: `Web ${this.core.useWebGPU ? 'GPU' : 'GL'}: <br> Stopped rendering. <br> FPS: 0 <br> Avg: ${avgFrameTime} ms/frame <br> Delta: ${this.deltaTime.toFixed(3)}s <br> PixelRatio: ${
					this.pixelRatio
			  }`;
	}
	private logFrameMetrics(renderDifference: number): void {
		const fps = this._frameNum > 0 ? (1000 / (this._timeSum / this._frameNum)).toFixed(1) : '0';
		console.debug(
			`Frame ${this._frameNum}: Rendering took ${renderDifference.toFixed(2)} ms. ` +
				`Avg: ${(this._timeSum / this._frameNum).toFixed(2)} ms/frame, FPS: ${fps}, ` +
				`Delta: ${this.deltaTime.toFixed(3)}s, Idle: ${this.idleTime.toFixed(2)}s, ` +
				`PixelRatio: ${this.pixelRatio}, Adaptive: ${this._adaptiveRendering}, ` +
				`KeepRendering: ${this._keepRendering}, ForceRender: ${this._forceRenderActive}`
		);
	}
	private removeLoadingGIFDom(): void {
		if (this.loadingDiv && this.core?.host.contains(this.loadingDiv)) {
			this.core.host.removeChild(this.loadingDiv);
			this.loadingDiv = null;
		}
	}
	public appendLoading(): void {
		const loadingDiv = document.createElement('div');
		loadingDiv.id = 'loading';
		Object.assign(loadingDiv.style, {
			position: 'relative',
			top: '50%',
			left: '50%',
			transform: 'translate(-50%, -50%)',
			zIndex: '9999',
			backgroundColor: 'rgba(255, 255, 255, 0.5)',
			padding: '10px',
			borderRadius: '8px',
		});

		const path = 'https://raw.githubusercontent.com/NamjuLee/data/master/map/loading.gif';
		const loadingImg = document.createElement('img');
		Object.assign(loadingImg, {
			src: path,
			style: { backgroundColor: 'transparent' },
			alt: 'Loading...',
			width: 120,
		});

		loadingDiv.appendChild(loadingImg);
		loadingDiv.style.position = 'absolute';
		this.loadingDiv = loadingDiv;
		this.core.host.appendChild(loadingDiv);
	}
	private resizeHandler = (): void => {
		if (!this.renderer || !this.core) return;

		const width = this.core.host.clientWidth;
		const height = this.core.host.clientHeight;

		this.renderer.setPixelRatio(this.pixelRatio);
		this.renderer.setSize(width, height);

		if (this.core.cameraWrapper?.camera instanceof THREE.PerspectiveCamera) {
			this.core.cameraWrapper.camera.aspect = width / height;
			this.core.cameraWrapper.camera.updateProjectionMatrix();
		}

		this.renderForce();
	};
	public disposeScene(): void {
		if (this.requestFrame !== null) {
			cancelAnimationFrame(this.requestFrame);
			this.requestFrame = null;
		}

		this.scene.traverse((object: THREE.Object3D) => {
			const mesh = object as THREE.Mesh;
			if (mesh.geometry && typeof mesh.geometry.dispose === 'function') {
				mesh.geometry.dispose();
			}

			const material = mesh.material as THREE.Material | THREE.Material[] | undefined;
			if (material) {
				const disposeTexture = (tex: THREE.Texture | null): void => {
					if (tex && typeof tex.dispose === 'function') {
						tex.dispose();
					}
				};

				if (Array.isArray(material)) {
					material.forEach((m) => {
						disposeTexture(m.map);
						disposeTexture(m.normalMap);
						disposeTexture(m.roughnessMap);
						disposeTexture(m.metalnessMap);
						disposeTexture(m.bumpMap);
						disposeTexture(m.alphaMap);
						disposeTexture(m.emissiveMap);
						if (typeof m.dispose === 'function') m.dispose();
					});
				} else {
					disposeTexture(material.map);
					disposeTexture(material.normalMap);
					disposeTexture(material.roughnessMap);
					disposeTexture(material.metalnessMap);
					disposeTexture(material.bumpMap);
					disposeTexture(material.alphaMap);
					disposeTexture(material.emissiveMap);
					if (typeof material.dispose === 'function') material.dispose();
				}
			}
		});

		const disposeEnvTexture = (tex: THREE.Texture | THREE.Color | null): void => {
			if (tex && 'dispose' in tex && typeof tex.dispose === 'function') {
				tex.dispose();
			}
		};
		disposeEnvTexture(this.scene.background);
		disposeEnvTexture(this.scene.environment);

		this.scene.background = null;
		this.scene.environment = null;

		const lights: THREE.Light[] = [];
		this.scene.traverse((obj: THREE.Object3D) => {
			if (obj instanceof THREE.Light) {
				lights.push(obj);
			}
		});
		lights.forEach((light) => this.scene.remove(light));

		this.scene.clear();
	}
}
