import { Configurator } from '../SceneWrapper/Configurator';
import { AppCommon } from '.';

export class CommonSandbox {
	public appCommon: AppCommon;
	private configurator: Configurator;
	constructor(appCommon: AppCommon) {
		this.appCommon = appCommon;
		this.configurator = this.appCommon.appCore.sceneWrapper.configurator;
	}
	// ......................... controlling scene
	public hideAll() {
		this.appCommon.appCore.sceneWrapper.hideAll();
		this.appCommon.renderForce();
	}
	public showHypercube() {
		this.appCommon.appCore.sceneWrapper?.hyperCube.show(true);
		this.appCommon.renderForce();
	}
	public hideHypercubeStatic() {
		this.appCommon.appCore.sceneWrapper?.hyperCube.show(false);
		this.appCommon.renderForce();
	}
	public showHypercubeStatic() {
		this.showHypercube();
	}
	public decompose() {
		this.appCommon.appCore.sceneWrapper.hyperCube?.decompose();
		this.appCommon.renderForce();
	}
	public toggleScene() {
		this.appCommon.appCore.sceneWrapper.activateGlobe = !this.appCommon.appCore.sceneWrapper.activateGlobe;
		this.appCommon.sampleCameraPositionIndex = 0;
		if (this.appCommon.appCore.sceneWrapper.activateGlobe) {
			this.appCommon.appCore.sceneWrapper.showGlobe();
		} else {
			this.appCommon.appCore.sceneWrapper.showStudioEnv();
		}
		this.appCommon.appCore.rendererCore.cameraStaring();
		this.appCommon.renderForce();
	}
	public showStudioEnv() {
		this.appCommon.appCore.sceneWrapper.hideAll();
		if (this.appCommon.appCore.sceneWrapper.studioEnv) {
			this.appCommon.appCore.sceneWrapper.studioEnv.show(!this.appCommon.appCore.sceneWrapper.studioEnv.meshFloor.visible);
			this.appCommon.appCore.sceneWrapper.hyperCube?.show(!this.appCommon.appCore.sceneWrapper.hyperCube?.visible);
		}
		this.appCommon.renderForce();
	}
	public showSubstation() {
		this.appCommon.appCore.sceneWrapper.hideAll();
		if (this.appCommon.appCore.sceneWrapper.substation) {
			this.appCommon.appCore.sceneWrapper.hyperCube?.show(true);
			this.appCommon.appCore.sceneWrapper.substation.showSubstation();
		}
		this.appCommon.renderForce();
	}
	public showSubstationDiorama() {
		this.appCommon.appCore.sceneWrapper.hideAll();
		if (this.appCommon.appCore.sceneWrapper.substation) {
			this.appCommon.appCore.sceneWrapper.hyperCube?.show(true);
			this.appCommon.appCore.sceneWrapper.substation.showSubstationDiorama();
		}
		this.appCommon.renderForce();
	}
	// ......................... end controlling scene
	public angleSolarPanel(v) {
		this.appCommon.renderForce();

		if (this.appCommon.appCore.sceneWrapper.hyperCube) {
			this.appCommon.appCore.sceneWrapper.hyperCube.angleSolarPanel = v;
		}
	}
	public getSubstationVisibility() {
		this.appCommon.renderForce();
		if (this.appCommon.appCore.sceneWrapper.substation) {
			return this.appCommon.appCore.sceneWrapper.substation.visibility;
		}
		return false;
	}
}
