import * as THREE from 'three';

import { Addon } from './';

import { loadFBX, loadFBXWithMat } from '../../../../../utils/ThreeUtils';

interface parmaHeight {
	radiusTop: number;
	radiusBottom: number;
	height: number;
	radialSegments: number;
}

export class Disco {
	public addon: Addon;

	private mesh: THREE.Group;
	private meshDisco: THREE.Group;
	private meshNeck: THREE.Mesh;

	private params: parmaHeight;

	constructor(addon: Addon) {
		this.addon = addon;
		this.mesh = new THREE.Group();
		this.mesh.name = 'Disco';
		this.mesh.userData = { obj: this };
		this.loadSolarPanel([addon.hypercubeParametric.configurator.BASE_URL + 'DiscoBall.fbx'], 0.25);
	}
	private loadSolarPanel = async (files, scale) => {
		// console.log(files, scale);

		this.params = {
			radiusTop: 1.35,
			radiusBottom: 1.35,
			height: 1,
			radialSegments: 48,
		};

		try {
			const loadPromises = files.map((file) =>
				// loadFBX(
				// 	file,
				// 	scale,
				// 	this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.rendererCore.useWebGPU,
				// 	this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.isPerformanceMode,
				// 	this.addon.hypercubeParametric.configurator.materials.clippingPlanes
				// )
				loadFBXWithMat(
					file,
					scale,
					this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.rendererCore.useWebGPU,
					this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.isPerformanceMode,
					this.addon.hypercubeParametric.configurator.materials.clippingPlanes,
					this.addon.hypercubeParametric.configurator.materials.MaterialClass,
					this.addon.hypercubeParametric.configurator.materials.addonMaterial
				)
			);

			const fbxModels = await Promise.all(loadPromises);
			fbxModels[0].rotation.z = -Math.PI * 0.5;

			this.meshDisco = fbxModels[0];
			this.meshDisco.position.y -= 1;
			this.mesh.add(this.meshDisco);

			const material = this.meshDisco.children[0].children[0].children[0].material;

			const geometry = new THREE.CylinderGeometry(this.params.radiusTop, this.params.radiusBottom, this.params.height, this.params.radialSegments, 1);
			this.meshNeck = new THREE.Mesh(geometry, material);
			this.meshNeck.castShadow = true;
			this.meshNeck.scale.y = this.params.height;

			this.meshNeck.position.y =
				this.addon.hypercubeParametric.params.height +
				this.addon.hypercubeParametric.params.groundY -
				this.addon.hypercubeParametric.params.thickness * 0.25 +
				this.addon.hypercubeParametric.params.WallUnit.height * 0.5;
			this.mesh.add(this.meshNeck);

			// this.cylinder.userData.obj = this;
			this.syncSizes();

			this.addon.hypercubeParametric.configurator.sceneWrapper.scene.add(this.mesh);
		} catch (error) {
			console.error('fail to load :', error);
		}
	};
	public setHight(value: number) {
		this.params.height = value;
		this.syncSizes();
	}
	public syncSizes() {
		const wallUnitOffset = this.addon.hypercubeParametric.params.WallUnit.height;

		if (this.mesh) {
			// this.mesh.position.y = this.addon.hypercubeParametric.params.height * 0.5 - this.addon.hypercubeParametric.params.thickness * 0.5;
			this.mesh.position.y = this.addon.hypercubeParametric.params.height + this.addon.hypercubeParametric.params.groundY + this.params.height;
		}

		if (this.meshNeck) {
			this.meshNeck.scale.y = this.params.height + wallUnitOffset;

			this.meshNeck.position.y =
				// this.addon.hypercubeParametric.params.height +
				// this.addon.hypercubeParametric.params.groundY +
				// -this.addon.hypercubeParametric.params.thickness * 0.25 - this.addon.hypercubeParametric.params.WallUnit.height * 0.5 -
				-this.params.height * 0.5 - wallUnitOffset;
		}
	}
	public toggleVisibility() {
		this.mesh.visible = !this.mesh.visible;
	}
}
